// Prepare only. A failed or unavailable SDK producer must not be dispatched as a passing gate.
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { renderAddonWorkflow } from './addon-workflow.mjs';
const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, '../../..');
const [approvalPath, output] = process.argv.slice(2);
if (!approvalPath || !output || !resolve(output).startsWith(`${resolve(repo, 'docs/superpowers')}/`)) throw new Error('usage: generate-addon.mjs APPROVAL_JSON NEW_BUNDLE');
const input = JSON.parse(readFileSync(approvalPath, 'utf8'));
const { source, sdk, sdkTree, rustSdk, cargoLockSha256 } = input;
if (![source, sdk, sdkTree, rustSdk].every(x => /^[0-9a-f]{40}$/.test(x ?? '')) || !/^[0-9a-f]{64}$/.test(cargoLockSha256 ?? '')) throw new Error('Exact source identities required');
const git = (...args) => execFileSync('git', args, { cwd: repo, encoding: 'utf8' }).trim();
if (git('show', '-s', '--format=%G?', source) !== 'G') throw new Error('Wallet source is not signed');
const sourceTree = git('rev-parse', `${source}^{tree}`);
const api = endpoint => JSON.parse(execFileSync('gh', ['api', endpoint], { maxBuffer: 8 * 1024 * 1024 }));
const commit = api(`repos/0xMiden/web-sdk/git/commits/${sdk}`);
if (commit.sha !== sdk || commit.tree?.sha !== sdkTree) throw new Error('SDK commit or tree mismatch');
const file = api(`repos/0xMiden/web-sdk/contents/Cargo.lock?ref=${sdk}`);
if (file.encoding !== 'base64' || typeof file.content !== 'string') throw new Error('SDK lockfile unavailable');
const lock = Buffer.from(file.content, 'base64');
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
if (hash(lock) !== cargoLockSha256 || !lock.toString('utf8').includes(rustSdk)) throw new Error('SDK lockfile or rust-sdk revision mismatch');
const bundle = resolve(output); mkdirSync(bundle, { recursive: false });
const paths = ['.github/workflows/issue1948-sdk-injection.yml', '.github/ci/v8-split/addon-builder.cjs'];
for (const filePath of paths) mkdirSync(dirname(join(bundle, filePath)), { recursive: true });
writeFileSync(join(bundle, paths[0]), renderAddonWorkflow(input));
copyFileSync(join(here, 'addon-builder.cjs'), join(bundle, paths[1]));
const manifest = { source, source_tree: sourceTree, sdk_source: sdk, sdk_tree: sdkTree, rust_sdk: rustSdk, cargo_lock_sha256: cargoLockSha256, proof_paths: paths, files: Object.fromEntries(paths.map(filePath => [filePath, hash(readFileSync(join(bundle, filePath)))])), purpose: 'Exact production-feature SDK Node addon producer, no dispatch', dispatched: false };
writeFileSync(join(bundle, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`);
console.log(JSON.stringify({ bundle, manifestSha256: hash(readFileSync(join(bundle, 'manifest.json'))), dispatched: false }));
